    },
    {
      "indicator": "MM50",
      "reading": "10.6702",
      "interpretation": "Média de médio prazo acima do preço — tendência de médio prazo baixista."
    },
    {
      "indicator": "MM200",
      "reading": "11.8006",
      "interpretation": "Média de longo prazo bem acima — viés estrutural de baixa."
    },
    {
